package com.mantou.salesdialer.contacts;
import android.app.*;import android.os.Bundle;import android.text.InputType;import android.util.AtomicFile;import android.widget.*;
import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
import com.mantou.salesdialer.contacts.PhoneIntakeModel.*;
/** Fixed private local staging UI. No identity, path, number or enable flag comes from Intent. */
public final class PhoneIntakeActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private PhoneIntakeStore store;private DataClass mode=DataClass.LOCAL_PHONE_INTAKE;private List<PhoneIntakeStore.Contact> contacts=List.of();private String selected="",message="正在读取资料区……";private boolean busy=true,rendering;private int generation;private final String sessionId=UUID.randomUUID().toString();
 private LocalDraftBatch.Preview batchPreview,listPreview;private EditText search;private Spinner filters;private ContactListView.Filter listFilter=ContactListView.Filter.ALL;private List<ContactListView.Row> visible=List.of();private PhoneIntakeStore.PlanView currentPlan;private List<PhoneIntakeStore.DraftView> drafts=List.of();private TextView status,notice;private Spinner targets;private final Map<String,Button> buttons=new LinkedHashMap<>();
 private boolean pilot(){return getPackageName().equals("com.mantou.salesdialer.pilot");}
 private interface Action{void run();}
 private PhoneIntakeStore.Contact chosen(){return contacts.stream().filter(c->c.id.equals(selected)&&visible.stream().anyMatch(r->r.targetId.equals(c.id))).findFirst().orElse(null);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);if(saved!=null){try{mode=DataClass.valueOf(saved.getString("mode",DataClass.LOCAL_PHONE_INTAKE.name()));}catch(Exception ignored){}selected=saved.getString("selected","");}
  LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);int pad=(int)(16*getResources().getDisplayMetrics().density);body.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);TextView title=new TextView(this);title.setTextSize(22);title.setText("本机号码暂存");body.addView(title);TextView hint=new TextView(this);hint.setText((pilot()?"尚未连接企业登录；受控通话需另页明确授权。":"未连接企业登录和拨号服务。")+"导入只保存资料；草稿须明确创建，不安排执行或拨电话。\n已有联系资格可直接记录，无需上传证明。列表仅显示掩码。");body.addView(hint);status=new TextView(this);status.setPadding(0,pad/2,0,pad/2);body.addView(status);search=input(false);search.setHint("搜索显示掩码或尾号");search.setContentDescription("搜索掩码或尾号");search.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(64)});body.addView(search);filters=new Spinner(this);filters.setContentDescription("按草稿资格筛选");filters.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"全部联系人","合格且无草稿","已有有效草稿","已有过时草稿","资格未确认或撤回","已拒绝联系"}));body.addView(filters);targets=new Spinner(this);targets.setContentDescription("选择暂存联系人");body.addView(targets);targets.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int i,long id){if(!rendering){selected=i>0&&i<=visible.size()?visible.get(i-1).targetId:"";controls();}}});
  button(body,"导入逐行号码",this::importDialog);button(body,"联系人资格与拒绝",this::contactDialog);button(body,"检查拨号边界",()->{var c=chosen();if(c!=null)submit("BOUNDARY",()->{String reason=store.boundary(c.id);message="真实提交已阻止："+reason+"。未创建任务或拨号请求。";});});button(body,"刷新暂存名单",()->submit("REFRESH",()->message="已读取最新状态。"));button(body,"切换号码资料区",()->new AlertDialog.Builder(this).setTitle("选择号码资料区").setItems(new String[]{"本机真实号码暂存（未认证）","格式测试区（生成数据，不转拨号目标）"},(d,index)->switchMode(index==0?DataClass.LOCAL_PHONE_INTAKE:DataClass.FORMAT_FIXTURE)).setNegativeButton("取消",null).show());
  button(body,"显式生成本地草稿",()->{var c=chosen();if(c!=null)submit("DRAFT_CREATE",()->{store.createDraft(c.id,c.revision);message="本地草稿已保存；不产生拨号许可或计划。";});});button(body,"显式刷新本地草稿",()->{var c=chosen();var d=drafts.stream().filter(v->v.draft.targetId.equals(selected)).findFirst().orElse(null);if(c!=null&&d!=null)submit("DRAFT_REFRESH",()->{store.refreshDraft(c.id,c.revision,d.draft.contactRevision);message="已明确刷新草稿快照；发送仍禁用。";});});
  button(body,"批量预览与生成草稿",()->submit("DRAFT_BATCH_PREVIEW",()->{batchPreview=store.previewDraftBatch();message="批量预览已读取；等待明确确认。";}));
  button(body,"编辑本地计划",this::planDialog);button(body,"暂停本地计划",()->{var seen=currentPlan;if(seen!=null)submit("PLAN_PAUSE",()->{store.pausePlan(seen.plan.version);message="计划已暂停；恢复须重新安排。";});});
  if(pilot())button(body,"受控通话与结果",()->{var c=chosen();android.content.Intent next=new android.content.Intent().setClassName(getPackageName(),"com.mantou.salesdialer.contacts.PilotActivity");if(c!=null)next.putExtra("targetId",c.id);startActivity(next);});
  notice=new TextView(this);notice.setPadding(0,pad/2,0,0);body.addView(notice);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence v,int st,int count,int after){}public void onTextChanged(CharSequence v,int st,int before,int count){if(!busy)render();}public void afterTextChanged(android.text.Editable e){}});filters.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> v){}public void onItemSelected(AdapterView<?> v,android.view.View row,int i,long id){listFilter=ContactListView.Filter.values()[i];if(!busy)render();}});controls();switchMode(mode);
 }
 private void button(LinearLayout body,String text,Action action){Button b=new Button(this);b.setText(text);buttons.put(text,b);body.addView(b);b.setOnClickListener(v->{if(!busy)action.run();});}
 private void controls(){for(Button b:buttons.values())b.setEnabled(!busy&&store!=null);buttons.get("联系人资格与拒绝").setEnabled(!busy&&chosen()!=null);buttons.get("检查拨号边界").setEnabled(!busy&&chosen()!=null);buttons.get("显式生成本地草稿").setEnabled(!busy&&chosen()!=null);buttons.get("显式刷新本地草稿").setEnabled(!busy&&chosen()!=null&&drafts.stream().anyMatch(d->d.draft.targetId.equals(selected)));buttons.get("编辑本地计划").setEnabled(!busy&&chosen()!=null&&currentPlan!=null&&drafts.stream().anyMatch(d->d.draft.targetId.equals(selected)));buttons.get("暂停本地计划").setEnabled(!busy&&currentPlan!=null);if(buttons.containsKey("受控通话与结果"))buttons.get("受控通话与结果").setEnabled(!busy&&mode==DataClass.LOCAL_PHONE_INTAKE&&chosen()!=null);targets.setEnabled(!busy&&!visible.isEmpty());search.setEnabled(!busy);filters.setEnabled(!busy);status.setText((mode==DataClass.FORMAT_FIXTURE?"格式测试区 · 绝不转为真实拨号目标":"本机真实号码暂存 · 未认证资料槽")+"\n显示 "+visible.size()+" / 联系人 "+contacts.size()+(pilot()?" · 响铃/接通待实际核对":" · 实际呼叫 0")+"\n本地草稿 "+drafts.size()+(pilot()?" · 生产外呼未开放，受控通话另页授权":" · 未接执行器/无尝试，真实发送固定禁用"));if(currentPlan!=null)status.append("\n本地计划版本 "+currentPlan.plan.version+" · "+(currentPlan.plan.paused?"暂停，须重新安排":SyntheticWorkspaceModel.formatTime(currentPlan.plan.dueAt)+" 北京时间 · "+currentPlan.status));notice.setText(busy?"正在处理……":message);}
 private static String safe(Exception e){String code=e.getMessage();return code!=null&&Set.of("STALE_BATCH","STALE_PLAN","PAST_DUE","OUTSIDE_WINDOW","INVALID_BEIJING_TIME","INVALID_TIME","STALE_DRAFT","DRAFT_NOT_FOUND","CONTACT_NOT_QUALIFIED","INVALID_BATCH","INVALID_INPUT","STALE_CONTACT","DO_NOT_CONTACT","NOT_FOUND","PHONE_STORE_INVALID","PHONE_STORE_TYPE_MISMATCH","PHONE_STORE_CLOSED","INVALID_CLOCK").contains(code)?code:"PHONE_INTAKE_FAILED";}
 private void switchMode(DataClass next){if(busy&&store!=null)return;busy=true;batchPreview=null;listPreview=null;visible=List.of();mode=next;contacts=List.of();drafts=List.of();currentPlan=null;selected="";render();worker.execute(()->{try{if(store!=null)store.close();store=null;store=PhoneIntakeStore.open(getApplicationContext(),next);store.recoverPlan();message="资料区已读取；切换不会复制或转换联系人。";publish("OPEN","");}catch(Exception e){fatal(safe(e));}});}
 private void submit(String action,Action work){if(busy||store==null)return;busy=true;controls();worker.execute(()->{String error="";try{work.run();}catch(Exception e){error=safe(e);message=human(error);}try{publish(action,error);}catch(Exception e){fatal(safe(e));}});}
 private void publish(String action,String error)throws Exception{var stable=store.intakeSnapshot();List<PhoneIntakeStore.Contact> snapshot=stable.contacts;List<PhoneIntakeStore.DraftView> draftSnapshot=stable.drafts;PhoneIntakeStore.PlanView planSnapshot=stable.plan;List<PhoneIntakeStore.PilotAttempt> attemptSnapshot=stable.attempts;JSONObject report=new JSONObject().put("source","LOCAL_PHONE_INTAKE_UI").put("ready",true).put("sessionId",sessionId).put("generation",++generation).put("action",action).put("errorCode",error).put("dataClass",mode.name()).put("dataDigest",stable.digest).put("productionAuthenticated",false).put("realCallsEnabled",false).put("actualPhoneCalls",pilot()?JSONObject.NULL:0).put("pilotCapability",pilot()).put("attemptCount",attemptSnapshot.size()).put("tasksCreated",draftSnapshot.size()).put("executionRequestsCreated",attemptSnapshot.size()).put("boundary",PhoneIntakeModel.submissionBoundary(mode));JSONArray rows=new JSONArray();for(var c:snapshot)rows.put(new JSONObject().put("id",c.id).put("maskedNumber",c.maskedNumber).put("qualification",c.qualification.name()).put("refused",c.refused).put("revision",c.revision));JSONArray draftRows=new JSONArray();for(var d:draftSnapshot)draftRows.put(new JSONObject().put("id",d.draft.id).put("targetId",d.draft.targetId).put("contactRevision",d.draft.contactRevision).put("status",d.status).put("dataClass",d.draft.dataClass.name()));report.put("plan",new JSONObject().put("version",planSnapshot.plan.version).put("targetId",planSnapshot.targetId).put("contactRevision",planSnapshot.plan.contactRevision).put("dueAt",planSnapshot.plan.dueAt).put("paused",planSnapshot.plan.paused).put("status",planSnapshot.status)).put("drafts",draftRows).put("draftCount",draftRows.length()).put("contacts",rows).put("total",snapshot.size());write(report);runOnUiThread(()->{if(isDestroyed()||isFinishing())return;contacts=snapshot;listPreview=stable.preview;drafts=draftSnapshot;currentPlan=planSnapshot;busy=false;render();if(action.equals("DRAFT_BATCH_PREVIEW"))showBatchDialog(batchPreview);});}
 private void write(JSONObject report)throws Exception{AtomicFile f=new AtomicFile(new File(getFilesDir(),"phone-intake-status.json"));FileOutputStream out=null;try{out=f.startWrite();out.write(report.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 private void fatal(String code){try{write(new JSONObject().put("source","LOCAL_PHONE_INTAKE_UI").put("ready",false).put("errorCode",code).put("actualPhoneCalls",pilot()?JSONObject.NULL:0));}catch(Exception ignored){}runOnUiThread(()->{busy=true;message="资料区读取失败，已停止。保留数据，不要清库重试。";controls();notice.setText(message);});}
 private void render(){List<String> labels=new ArrayList<>();labels.add("请选择当前显示的联系人");if(listPreview!=null){Map<String,String> masks=new HashMap<>();for(var c:contacts)masks.put(c.id,c.maskedNumber);var result=ContactListView.project(listPreview,masks,listFilter,search.getText().toString(),selected);visible=result.rows;selected=result.selectedId;}else{visible=List.of();selected="";}int index=0;for(int i=0;i<visible.size();i++){var row=visible.get(i);var c=contacts.stream().filter(v->v.id.equals(row.targetId)).findFirst().orElseThrow();labels.add(c.maskedNumber+" · "+(c.refused?"拒绝联系":q(c.qualification)));if(c.id.equals(selected))index=i+1;}rendering=true;targets.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));targets.setSelection(index,false);rendering=false;controls();}
 private void showBatchDialog(LocalDraftBatch.Preview preview){if(preview==null||isDestroyed()||isFinishing())return;String summary="本资料区全部联系人（不受列表筛选影响）共 "+preview.rows.size()+" 条\n可新建 "+preview.count(LocalDraftBatch.Status.CREATE)+"\n已有有效草稿 "+preview.count(LocalDraftBatch.Status.EXISTING_CURRENT)+"\n过时草稿（需逐条明确刷新） "+preview.count(LocalDraftBatch.Status.EXISTING_STALE)+"\n资格未确认/撤回 "+preview.count(LocalDraftBatch.Status.NOT_QUALIFIED)+"\n拒绝联系 "+preview.count(LocalDraftBatch.Status.REFUSED)+"\n仅创建合格且无草稿者；不会安排计划、授权或拨号。资料变化后须重新预览。";var dialog=new AlertDialog.Builder(this).setTitle("批量本地草稿预览").setMessage(summary).setNegativeButton("取消",null);if(preview.count(LocalDraftBatch.Status.CREATE)>0)dialog.setPositiveButton("确认生成合格草稿",(d,w)->submit("DRAFT_BATCH_CREATE",()->{int created=store.createDraftBatch(preview);message="已一次保存 "+created+" 个本地草稿；既有草稿保持，无计划或拨号许可产生。";}));dialog.show();}
 private EditText input(boolean multiple){EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS|(multiple?InputType.TYPE_TEXT_FLAG_MULTI_LINE:0));e.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);e.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);return e;}
 private void importDialog(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);EditText rows=input(true);rows.setMinLines(4);rows.setHint("每行一个大陆11位手机号；单批最多200行");rows.setContentDescription("逐行号码输入");form.addView(rows);EditText source=input(false);source.setHint("本批来源说明（无需上传证明）");source.setContentDescription("批次来源输入");form.addView(source);Spinner qualification=new Spinner(this);qualification.setContentDescription("批次联系资格");qualification.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"尚未确认","我已有联系资格或同意记录","已撤回"}));form.addView(qualification);TextView hint=new TextView(this);hint.setText("国家码、座机、分机暂不转换。无效/不支持行仍记录结果，只有合法行形成暂存联系人；整批写失败回滚。格式判断不是号码存在或资格核验。");form.addView(hint);ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle(mode==DataClass.FORMAT_FIXTURE?"导入格式测试数据":"导入本机号码资料").setView(scroll).setNegativeButton("取消",null).setPositiveButton("保存资料",(d,w)->{String text=rows.getText().toString(),src=source.getText().toString();Qualification q=Qualification.values()[qualification.getSelectedItemPosition()];submit("IMPORT",()->{var b=store.importRows(PhoneIntakeModel.rows(text),src,q);message="本批：导入"+b.count("IMPORTED")+"，重复"+b.count("DUPLICATE")+"，暂不支持"+b.count("UNSUPPORTED")+"，无效"+b.count("INVALID")+"。未产生拨号任务。";});}).show();}
 private void planDialog(){var c=chosen();var d=drafts.stream().filter(v->v.draft.targetId.equals(selected)).findFirst().orElse(null);var seen=currentPlan;if(c==null||d==null||seen==null)return;java.time.ZonedDateTime suggested=java.time.ZonedDateTime.now(java.time.ZoneOffset.ofHours(8)).plusMinutes(5).withSecond(0).withNano(0);while(suggested.getDayOfWeek().getValue()>5||suggested.getHour()>=18||suggested.getHour()<9)suggested=suggested.getHour()<9?suggested.withHour(9).withMinute(0):suggested.plusDays(1).withHour(9).withMinute(0);EditText time=input(false);time.setText(SyntheticWorkspaceModel.formatTime(suggested.toInstant().toEpochMilli()));time.setContentDescription("本地计划北京时间");new AlertDialog.Builder(this).setTitle("编辑本地计划元数据").setMessage(c.maskedNumber+" · 北京时间 yyyy-MM-dd HH:mm\n仅保存计划，不设置闹钟或执行。重新进入资料区会暂停旧计划。").setView(time).setNegativeButton("取消",null).setPositiveButton("保存本地计划",(dialog,which)->{String value=time.getText().toString();submit("PLAN_ARRANGE",()->{store.arrangeDraft(c.id,seen.plan.version,c.revision,d.draft.contactRevision,SyntheticWorkspaceModel.parseTime(value));message="计划元数据已保存；未接执行器，不会拨号。";});}).show();}
 private void contactDialog(){var c=chosen();if(c==null)return;new AlertDialog.Builder(this).setTitle(c.maskedNumber+" · 联系人操作").setItems(new String[]{"资格设为尚未确认","记录已有联系资格","记录资格已撤回","拒绝联系"},(d,index)->submit("CONTACT_"+index,()->{if(index==3)store.refuse(c.id,c.revision);else store.qualify(c.id,c.revision,Qualification.values()[index],"USER_DECLARATION");message="已保存声明/拒绝记录；真实发送仍禁用。";})).setNegativeButton("取消",null).show();}
 private static String q(Qualification q){switch(q){case CONFIRMED:return "资格已声明";case WITHDRAWN:return "资格已撤回";default:return "资格尚未确认";}}
 private static String human(String code){switch(code){case "STALE_BATCH":return "名单或草稿已变化，整批未保存；请重新预览后确认。";case "INVALID_BATCH":return "请检查单批1～200行、每行不超过128字符、来源1～200字符和资格选项。整批未保存。";case "STALE_CONTACT":return "记录已变化，请刷新后重新操作。";case "STALE_PLAN":return "计划已变化，请刷新后重新安排。";case "OUTSIDE_WINDOW":return "请选择北京时间周一至周五09:00至18:00前。";case "PAST_DUE":return "时间已过，请明确选择新时间；不会补拨。";case "INVALID_BEIJING_TIME":return "请输入有效日期和时间：yyyy-MM-dd HH:mm。";case "STALE_DRAFT":return "草稿已经过时，请明确刷新；不会自动替换旧快照。";case "DRAFT_NOT_FOUND":return "请先明确生成本地草稿。";case "CONTACT_NOT_QUALIFIED":return "当前联系资格尚未确认或已撤回，草稿操作已停止。";case "DO_NOT_CONTACT":return "已拒绝联系，不能用资格修改或重导入解除。";default:return "操作未完成，请刷新核对；不会重试或拨号。";}}
 @Override protected void onSaveInstanceState(Bundle saved){saved.putString("mode",mode.name());saved.putString("selected",selected);super.onSaveInstanceState(saved);}
 @Override protected void onDestroy(){worker.execute(()->{if(store!=null)store.close();});worker.shutdown();super.onDestroy();}
}
